    {'dn_no': 'DN-301', 'supplier': 'Eastern Raw Materials', 'net_amount': 3200.0, 'reason': 'Defective grade silk yarn'},
    {'dn_no': 'DN-302', 'supplier': 'Precision Tools Corp', 'net_amount': 1450.0, 'reason': 'Specification mismatch on drill bits'}
